133	function getCategoryBadge(category) {
134	    const currentLang = localStorage.getItem('app_lang') || 'ru';
135	
136	    const badges = {
137	        cleaning: {
138	            ru: 'Клининг', en: 'Cleaning', fr: 'Nettoyage', it: 'Pulizia', es: 'Limpieza', de: 'Reinigung', nl: 'Schoonmaak',
139	            class: 'badge-cleaning'
140	        },
141	        furniture: {
142	            ru: 'Мебель', en: 'Furniture', fr: 'Mobilier', it: 'Mobili', es: 'Muebles', de: 'Möbel', nl: 'Meubels',
143	            class: 'badge-montage'
144	        },
145	        restoration: {
146	            ru: 'Реставрация', en: 'Restoration', fr: 'Restauration', it: 'Restauro', es: 'Restauración', de: 'Restaurierung', nl: 'Restauratie',
147	            class: 'badge-repair'
148	        },
149	        relocation: {
150	            ru: 'Переезд', en: 'Relocation', fr: 'Déménagement', it: 'Trasloco', es: 'Mudanza', de: 'Umzug', nl: 'Verhuizing',
151	            class: 'badge-cleaning'
152	        }
153	    };
154	
155	    const item = badges[category] || {
156	        ru: 'Услуга', en: 'Service', fr: 'Service', it: 'Servizio', es: 'Servicio', de: 'Dienstleistung', nl: 'Dienst',
157	        class: 'badge-cleaning'
158	    };
159	
160	    return {
161	        label: item[currentLang] || item.ru,
162	        class: item.class
163	    };
164	}
