166	function getIconForService(category) {
167	    const icons = {
168	        'cleaning': '✨',
169	        'furniture': '🪑',
170	        'restoration': '🎨',
171	        'relocation': '📦'
172	    };
173	    return icons[category] || '🛠️';
174	}
