176	export function renderServiceCard(service) {
177	    const currentLang = localStorage.getItem('app_lang') || 'ru';
178	
179	    const orderBtnText = {
180	        ru: 'Заказать',
181	        en: 'Order',
182	        fr: 'Commander',
183	        it: 'Ordina',
184	        es: 'Pedir',
185	        de: 'Bestellen',
186	        nl: 'Bestellen'
187	    };
188	    const btnText = orderBtnText[currentLang] || orderBtnText.ru;
189	
190	    const card = document.createElement('div');
191	    card.className = 'service-card';
192	    
193	    const badge = getCategoryBadge(service.category);
194	    const icon = getIconForService(service.category);
195	
196	    card.innerHTML = `
197	        <div class="card-header">
198	            <span class="service-icon" style="font-size: 1.5rem;">${icon}</span>
199	            <span class="badge ${badge.class}">${badge.label}</span>
200	        </div>
201	        <h3 class="service-title">${service.title}</h3>
202	        <p class="service-desc">${service.description}</p>
203	        <div class="card-footer">
204	            <span class="service-price">${service.price}</span>
205	            <a href="#/contacts" class="btn-card">${btnText}</a>
206	        </div>
207	    `;
208	    return card;
209	}

